record.field:
for sol in self:
    sol['x_item_number'] = False

for order in self.order_id:
    numbers = {}
    l1 = l2 = l3 = 0
    last_header = False
    rows = order.order_line.filtered(lambda s: s.display_type in [False, 'line_section', 'line_subsection']).sorted('sequence')
    for row in rows:
        # top-level: section, or product above the first section
        if row.display_type == 'line_section' or (not row.display_type and not last_header):
            l1 += 1
        # middle-level: subsection, or product directly under a section
        elif row.display_type == 'line_subsection' or last_header == 'line_section':
            l2 += 1
        # bottom-level: product under a subsection
        else:
            l3 += 1
        if row.display_type == 'line_section':
            l2 = l3 = 0
        elif row.display_type == 'line_subsection':
            l3 = 0
        if row.display_type:
            last_header = row.display_type
        numbers[row.id] = "".join(["%s." % n for n in [l1, l2, l3] if n])
    for sol in self.filtered(lambda s: s.order_id == order):
        sol['x_item_number'] = numbers.get(sol.id, False)
